generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(xsd:decimal(?avgReturnsPct)) AS ?categoryAvgReturnsPct)
       (AVG(xsd:decimal(?avgSharpeRatio)) AS ?categoryAvgSharpeRatio)
       (AVG(xsd:decimal(?riskScore)) AS ?categoryAvgRiskScore)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:returnsPct ?returnsPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?sharpe)) AS ?avgSharpeRatio)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:avgSharpeRatio ?sharpe .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?riskScore)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?investor .
      ?ph wm:riskScore ?riskScore .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?category . }
  FILTER(BOUND(?category))
}
GROUP BY ?category

